CREATE UNIQUE INDEX IF NOT EXISTS idx_reconcile_presets_company_id_name ON banking.reconcile_presets (company_id, name) WHERE (metadata->>'deleted_at') IS NULL;

CREATE INDEX IF NOT EXISTS idx_reconcile_presets_company_id_status_priority ON banking.reconcile_presets (company_id, status, priority);

-- GIN index for audit metadata JSONB queries
